stack.pseudocode:
class ArrayStack:
    def __init__(self, capacity):
        self.data = [None] * capacity
        self.top = -1  # 비어 있음

    def push(self, x):  # O(1)
        if self.top == len(self.data) - 1:
            raise OverflowError('스택 오버플로')
        self.top += 1
        self.data[self.top] = x

    def pop(self):  # O(1), 후입선출
        if self.top == -1:
            raise IndexError('스택 언더플로')
        x = self.data[self.top]
        self.top -= 1
        return x

    def peek(self):
        if self.top == -1:
            raise IndexError('스택 언더플로')
        return self.data[self.top]

stack-based-virtual-machine.pseudocode:
def run(code):
    stack = []  # 피연산자 스택 (레지스터 없음)
    for op, arg in code:
        if op == 'PUSH':
            stack.append(arg)
        else:  # 이항 연산: pop 2개 → 결과 push
            b = stack.pop()  # 오른쪽 피연산자 먼저
            a = stack.pop()
            if op == 'ADD':
                stack.append(a + b)
            elif op == 'SUB':
                stack.append(a - b)
            elif op == 'MUL':
                stack.append(a * b)
    return stack.pop()

# (2+3)*4 → PUSH 2, PUSH 3, ADD, PUSH 4, MUL
# 스택: [2] → [2,3] → [5] → [5,4] → [20]

stacking.pseudocode:
def stacking_fit(X, y, base_models, meta_model, k=5):
    n = len(X)
    oof = [[0.0] * len(base_models) for _ in range(n)]
    for tr_idx, va_idx in kfold(n, k):
        for j, m in enumerate(base_models):
            m.fit(X[tr_idx], y[tr_idx])
            preds = m.predict(X[va_idx])
            for i, p in zip(va_idx, preds):
                oof[i][j] = p  # 학습에 안 쓴 폴드만 예측
    meta_model.fit(oof, y)  # 기반 예측값 → 메타 특성
    for m in base_models:
        m.fit(X, y)  # 추론용: 전체 데이터로 재학습
    return base_models, meta_model

def stacking_predict(x, base_models, meta_model):
    z = [m.predict([x])[0] for m in base_models]
    return meta_model.predict([z])[0]

