state-pattern.pseudocode:
class State:  # 상태 인터페이스
    def handle(self, ctx):
        raise NotImplementedError

class Green(State):
    def handle(self, ctx):
        print('통행')
        ctx.state = Yellow()  # 다음 상태로 전이

class Yellow(State):
    def handle(self, ctx):
        print('주의')
        ctx.state = Red()

class Red(State):
    def handle(self, ctx):
        print('정지')
        ctx.state = Green()

class TrafficLight:  # Context
    def __init__(self):
        self.state = Green()

    def request(self):  # if/switch 없이 현재 상태에 위임
        self.state.handle(self)

state-space-search.pseudocode:
def graph_search(start, is_goal, successors, mode='bfs'):
    open_list = [(start, [start])]  # OPEN: 미확장 (상태, 경로)
    closed = set()  # CLOSED: 확장 완료 상태
    while open_list:
        idx = 0 if mode == 'bfs' else -1  # BFS 큐, DFS 스택
        state, path = open_list.pop(idx)
        if is_goal(state):  # 목표 검사
            return path  # 초기→목표 상태 열 = 해
        if state in closed:
            continue
        closed.add(state)
        for nxt in successors(state):  # 후계 함수(연산자)
            if nxt not in closed:
                open_list.append((nxt, path + [nxt]))
    return None  # 해 없음

statistical-usage-testing.pseudocode:
def generate_test_case(model, start, end):
    # model[s] = [(다음 상태, 전이 확률), ...] 마르코프 사용 모델
    path, s = [start], start
    while s != end:
        r, acc = random(), 0.0
        for nxt, p in model[s]:
            acc += p
            if r < acc:  # 사용 확률에 비례해 다음 상태 선택
                break
        s = nxt  # 반올림 오차 시 마지막 후보
        path.append(s)
    return path  # 하나의 테스트 케이스(사용 시나리오)

def estimate_mttf(total_run_time, failures):
    # 실패 간 평균 시간으로 신뢰도 추정 (실패 0이면 하한만)
    return total_run_time / max(failures, 1)

stochastic-gradient-descent.pseudocode:
def sgd(theta, data, grad_fn, lr=0.1, batch=32,
        epochs=10, decay=0.9):
    for epoch in range(epochs):
        shuffle(data)  # 매 에폭 순서 무작위화
        for k in range(0, len(data), batch):
            mb = data[k:k + batch]  # 미니배치
            g = grad_fn(theta, mb)  # 미니배치 평균 기울기
            theta = [t - lr * gi for t, gi in zip(theta, g)]
        lr *= decay  # 학습률 감쇠로 진동 완화
    return theta

