stratified-k-fold.pseudocode:
def stratified_kfold(labels, k):
    folds = [[] for _ in range(k)]
    by_class = {}
    for i, c in enumerate(labels):
        by_class.setdefault(c, []).append(i)
    for idx in by_class.values():  # 클래스별로 따로 분배
        shuffle(idx)
        for j, i in enumerate(idx):
            folds[j % k].append(i)  # 순환 배치 → 비율 유지
    for f in range(k):
        test = folds[f]
        train = [i for g in range(k) if g != f
                 for i in folds[g]]
        yield train, test

stream-cipher.pseudocode:
def stream_encrypt(key, nonce, data):
    ks = keystream(key, nonce, len(data))  # 키스트림 생성
    return bytes(d ^ k for d, k in zip(data, ks))

def stream_decrypt(key, nonce, data):
    return stream_encrypt(key, nonce, data)  # XOR은 자기 역원

# 같은 (key, nonce) 재사용 시
# C1 XOR C2 = P1 XOR P2 → 평문 정보 노출
# 따라서 메시지마다 nonce를 새로 사용

streaming-api-for-xml.pseudocode:
def sum_prices(reader):  # reader: XMLStreamReader 커서
    total, in_price = 0.0, False
    while reader.has_next():  # 응용이 다음 이벤트를 당김(Pull)
        event = reader.next()
        if event == START_ELEMENT:
            in_price = reader.local_name() == 'price'
        elif event == CHARACTERS and in_price:
            total += float(reader.text())  # 필요한 값만 처리
        elif event == END_ELEMENT:
            in_price = False
    reader.close()
    return total  # 메모리 사용량은 문서 크기와 무관
